module tram_explosion #(\n    parameter MAX_R = 4,\n    parameter MAX_C = 4,\n    parameter MAX_X = 4,\n    parameter MAX_L = 4,\n    parameter CLK_LIMIT = 100\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [MAX_R*MAX_C*2-1:0] grid,\n    output reg [3:0] explosions,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] IDLE                 = 4'd0;\n    localparam [3:0] INIT                 = 4'd1;\n    localparam [3:0] FIND_CLOSEST         = 4'd2;\n    localparam [3:0] CHECK_CONFLICTS      = 4'd3;\n    localparam [3:0] RESOLVE_EXPLOSIONS   = 4'd4;\n    localparam [3:0] RESOLVE_SEATING      = 4'd5;\n    localparam [3:0] UPDATE_GRID          = 4'd6;\n    localparam [3:0] CHECK_IF_MORE_ROUNDS = 4'd7;\n    localparam [3:0] DONE_STATE           = 4'd8;\n\n    reg [3:0] state, next_state;\n    reg [3:0] explosion_cnt, next_explosion_cnt;\n    reg [7:0] clock_counter, next_clock_counter;\n\n    reg [MAX_R*MAX_C*2-1:0] current_grid, next_current_grid;\n    reg [3:0] x_pos [0:MAX_X-1];\n    reg [2:0] x_count, next_x_count;\n    reg [3:0] l_pos [0:MAX_L-1];\n    reg [2:0] l_count, next_l_count;\n\n    reg [3:0] x_target_l [0:MAX_X-1];\n    reg [15:0] x_target_dist [0:MAX_X-1];\n    reg [MAX_X-1:0] l_target_mask [0:MAX_L-1];\n    reg [15:0] l_target_min_dist [0:MAX_L-1];\n\n    integer i, j, k;\n\n    // Helper function to get cell value\n    function [1:0] get_cell;\n        input [MAX_R*MAX_C*2-1:0] grid_val;\n        input [5:0] index;\n        begin\n            get_cell = grid_val[index*2 +: 2];\n        end\n    endfunction\n\n    // Helper function to compute squared distance\n    function [15:0] compute_dist;\n        input [3:0] pos1, pos2;\n        integer r1, c1, r2, c2;\n        begin\n            r1 = pos1 / MAX_C;\n            c1 = pos1 % MAX_C;\n            r2 = pos2 / MAX_C;\n            c2 = pos2 % MAX_C;\n            compute_dist = (r1 - r2)*(r1 - r2) + (c1 - c2)*(c1 - c2);\n        end\n    endfunction\n\n    // State register\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            explosion_cnt <= 4'd0;\n            clock_counter <= 8'd0;\n            // Initialize all array elements properly\n            for (i = 0; i < MAX_X; i = i + 1) begin\n                x_pos[i] <= 4'd0;\n                x_target_l[i] <= 4'd0;\n                x_target_dist[i] <= 16'd0;\n            end\n            for (j = 0; j < MAX_L; j = j + 1) begin\n                l_pos[j] <= 4'd0;\n                l_target_mask[j] <= {MAX_X{1'b0}};\n                l_target_min_dist[j] <= 16'd0;\n            end\n            x_count <= 3'd0;\n            l_count <= 3'd0;\n            current_grid <= {MAX_R*MAX_C*2{1'b0}};\n        end else begin\n            state <= next_state;\n            explosion_cnt <= next_explosion_cnt;\n            clock_counter <= next_clock_counter;\n\n            // Update array elements through individual assignment\n            if (next_state == INIT) begin\n                x_count <= 3'd0;\n                l_count <= 3'd0;\n                for (i = 0; i < MAX_X; i = i + 1) begin\n                    x_pos[i] <= next_current_grid[i*2 +: 2] == 2'b01 ? i : x_pos[i];\n                    x_count <= (next_current_grid[i*2 +: 2] == 2'b01) ? x_count + 1 : x_count;\n                end\n                for (j = 0; j < MAX_L; j = j + 1) begin\n                    l_pos[j] <= next_current_grid[j*2 +: 2] == 2'b10 ? j : l_pos[j];\n                    l_count <= (next_current_grid[j*2 +: 2] == 2'b10) ? l_count + 1 : l_count;\n                end\n            end else begin\n                x_count <= next_x_count;\n                l_count <= next_l_count;\n                for (i = 0; i < MAX_X; i = i + 1) begin\n                    x_target_l[i] <= x_target_l[i];\n                    x_target_dist[i] <= x_target_dist[i];\n                end\n            end\n            current_grid <= next_current_grid;\n        end\n    end\n\n    // Next state and datapath\n    always @(*) begin\n        next_state = state;\n        next_explosion_cnt = explosion_cnt;\n        next_clock_counter = clock_counter + 8'd1;\n        next_current_grid = current_grid;\n        next_x_count = x_count;\n        next_l_count = l_count;\n\n        done = 1'b0;\n\n        case (state)\n            IDLE: begin\n                next_clock_counter = 8'd0;\n                next_explosion_cnt = 4'd0;\n                if (start) begin\n                    next_current_grid = grid;\n                    next_state = INIT;\n                end else begin\n                    next_state = IDLE;\n                end\n            end\n\n            INIT: begin\n                next_state = FIND_CLOSEST;\n            end\n\n            FIND_CLOSEST: begin\n                for (i = 0; i < MAX_X; i = i + 1) begin\n                    if (i < x_count) begin\n                        next_explosion_cnt = explosion_cnt;\n                        // Default closest distance\n                        x_target_dist[i] = 16'hFFFF;\n                        // Find closest L for each X\n                        for (j = 0; j < MAX_L; j = j + 1) begin\n                            if (j < l_count) begin\n                                automatic integer dist = compute_dist(x_pos[i], l_pos[j]);\n                                if (dist < x_target_dist[i]) begin\n                                    x_target_dist[i] = dist;\n                                    x_target_l[i] = j;\n                                end\n                            end\n                        end\n                    end\n                end\n                next_state = CHECK_CONFLICTS;\n            end\n\n            CHECK_CONFLICTS: begin\n                // Initialize target masks\n                for (j = 0; j < MAX_L; j = j + 1) begin\n                    l_target_mask[j] = {MAX_X{1'b0}};\n                    l_target_min_dist[j] = 16'hFFFF;\n                end\n                // Build masks for each L from X targets\n                for (i = 0; i < x_count; i = i + 1) begin\n                    j = x_target_l[i];\n                    l_target_mask[j] = l_target_mask[j] | (1 << i);\n                    if (x_target_dist[i] < l_target_min_dist[j]) begin\n                        l_target_min_dist[j] = x_target_dist[i];\n                    end\n                end\n                next_state = RESOLVE_EXPLOSIONS;\n            end\n\n            RESOLVE_EXPLOSIONS: begin\n                for (j = 0; j < l_count; j = j + 1) begin\n                    automatic integer x_count_for_l = 0;\n                    automatic reg [MAX_X-1:0] mask = l_target_mask[j];\n                    // Count Xs targeting this L\n                    for (i = 0; i < MAX_X; i = i + 1) begin\n                        if (mask[i]) x_count_for_l = x_count_for_l + 1;\n                    end\n                    // Check for conflict (>=2 Xs) with equal distance\n                    if (x_count_for_l >= 2) begin\n                        automatic integer all_equal = 1;\n                        for (i = 0; i < MAX_X; i = i + 1) begin\n                            if (mask[i] && x_target_dist[i] != l_target_min_dist[j]) begin\n                                all_equal = 0;\n                            end\n                        end\n                        if (all_equal) begin\n                            next_explosion_cnt = explosion_cnt + 4'd1;\n                        end\n                    end\n                end\n                next_state = RESOLVE_SEATING;\n            end\n\n            RESOLVE_SEATING: begin\n                // Remove X and L according to rules\n                automatic reg [MAX_X-1:0] removed_x = {MAX_X{1'b0}};\n                automatic reg [MAX_L-1:0] removed_l = {MAX_L{1'b0}};\n\n                for (j = 0; j < l_count; j = j + 1) begin\n                    automatic reg [MAX_X-1:0] mask = l_target_mask[j];\n                    automatic integer x_count_for_l = 0;\n                    for (i = 0; i < MAX_X; i = i + 1) begin\n                        if (mask[i]) x_count_for_l = x_count_for_l + 1;\n                    end\n\n                    if (x_count_for_l >= 2) begin\n                        automatic integer all_equal = 1;\n                        for (i = 0; i < MAX_X; i = i + 1) begin\n                            if (mask[i] && x_target_dist[i] != l_target_min_dist[j]) all_equal = 0;\n                        end\n                        if (all_equal) begin\n                            // Explosion: remove all X and L\n                            removed_x = removed_x | mask;\n                            removed_l[j] = 1'b1;\n                        end else begin\n                            // Find unique closest\n                            automatic integer hit_count = 0;\n                            for (i = 0; i < MAX_X; i = i + 1) begin\n                                if (mask[i] && x_target_dist[i] == l_target_min_dist[j]) begin\n                                    hit_count = hit_count + 1;\n                                end\n                            end\n                            if (hit_count == 1) begin\n                                for (i = 0; i < MAX_X; i = i + 1) begin\n                                    if (mask[i] && x_target_dist[i] == l_target_min_dist[j]) begin\n                                        removed_x[i] = 1'b1;\n                                        removed_l[j] = 1'b1;\n                                        break;\n                                    end\n                                end\n                            end\n                        end\n                    end else if (x_count_for_l == 1) begin\n                        // Single X to L pairing\n                        for (i = 0; i < MAX_X; i = i + 1) begin\n                            if (mask[i]) begin\n                                removed_x[i] = 1'b1;\n                                removed_l[j] = 1'b1;\n                                break;\n                            end\n                        end\n                    end\n                end\n\n                // Update X count\n                next_x_count = 0;\n                for (i = 0; i < MAX_X; i = i + 1) begin\n                    if (i < x_count && !removed_x[i]) begin\n                        next_x_count = next_x_count + 1;\n                    end\n                end\n\n                // Update L count\n                next_l_count = 0;\n                for (j = 0; j < MAX_L; j = j + 1) begin\n                    if (j < l_count && !removed_l[j]) begin\n                        next_l_count = next_l_count + 1;\n                    end\n                end\n\n                next_state = UPDATE_GRID;\n            end\n\n            UPDATE_GRID: begin\n                // Rebuild grid (simplified for this implementation)\n                // Just pass through for counting purposes\n                next_state = CHECK_IF_MORE_ROUNDS;\n            end\n\n            CHECK_IF_MORE_ROUNDS: begin\n                if ((next_x_count > 0) && (next_l_count > 0) && (clock_counter < CLK_LIMIT)) begin\n                    next_state = FIND_CLOSEST;\n                end else begin\n                    next_state = DONE_STATE;\n                end\n            end\n\n            DONE_STATE: begin\n                done = 1'b1;\n                next_state = IDLE;\n            end\n\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // Output explosion count\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            explosions <= 4'd0;\n        end else if (state == DONE_STATE) begin\n            explosions <= explosion_cnt;\n        end\n    end\n\nendmodule\n